    void onPendingBinaryRequest(uint32_t tag) override;
    void onPendingTelemetryRequest(uint32_t tag) override;
    void onPendingPathDiscoveryRequest(uint32_t tag) override;
    void onSentRoute(bool sent_flood) override;
